"""matplotlib.legend_handler — legend handler stubs."""


class HandlerBase:
    """Base class for legend handlers — knows how to build the legend-
    entry artist(s) for a given source artist. Real subclasses below
    return concrete Line2D/Rectangle proxies in their swatch rectangle.
    """

    def __init__(self, xpad=0, ypad=0, update_func=None):
        self._xpad = xpad
        self._ypad = ypad
        self._update_func = update_func

    def legend_artist(self, legend, orig_handle, fontsize, handlebox):
        """Build the artist for the legend entry and add it to ``handlebox``.
        Returns the first new artist (or ``None`` if nothing was created)."""
        artists = self.create_artists(
            legend, orig_handle,
            getattr(handlebox, 'xdescent', 0),
            getattr(handlebox, 'ydescent', 0),
            getattr(handlebox, 'width', 1.0),
            getattr(handlebox, 'height', 1.0),
            fontsize,
            getattr(handlebox, 'get_transform', lambda: None)())
        for a in artists:
            try: handlebox.add_artist(a)
            except Exception: pass
        return artists[0] if artists else None

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        """Default: empty swatch. Subclasses override."""
        return []

    def update_prop(self, legend_handle, orig_handle, legend):
        """Copy styling properties from ``orig_handle`` onto ``legend_handle``
        so the swatch matches the source artist."""
        if self._update_func is not None:
            try: self._update_func(legend_handle, orig_handle)
            except Exception: pass
        try:
            legend_handle.update_from(orig_handle)
        except Exception:
            pass

    def adjust_drawing_area(self, legend, orig_handle, xdescent, ydescent,
                             width, height, fontsize):
        """Apply legend padding to the drawing area. Returns the
        adjusted ``(xdescent, ydescent, width, height)`` tuple."""
        xd = xdescent - self._xpad * fontsize
        yd = ydescent - self._ypad * fontsize
        w  = width    - self._xpad * 2 * fontsize
        h  = height   - self._ypad * 2 * fontsize
        return xd, yd, w, h


class HandlerLine2D(HandlerBase):
    """Draw a tiny Line2D as the legend swatch, matching the source
    line's color/linewidth/linestyle."""

    def __init__(self, marker_pad=0.3, numpoints=None, **kwargs):
        super().__init__(**kwargs)
        self._marker_pad = marker_pad
        self._numpoints = numpoints if numpoints is not None else 1

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        xs = [-xdescent, width - xdescent]
        ys = [height / 2 - ydescent, height / 2 - ydescent]
        # Build a Line2D mirroring orig_handle's styling.
        kwargs = {}
        for attr in ('color', 'linewidth', 'linestyle', 'alpha', 'marker',
                      'markeredgecolor', 'markerfacecolor', 'markersize'):
            getter = getattr(orig_handle, f'get_{attr}', None)
            if getter is not None:
                try: kwargs[attr] = getter()
                except Exception: pass
        return [Line2D(xs, ys, **kwargs)]


class HandlerPatch(HandlerBase):
    """Draw a filled rectangle as the legend swatch."""

    def __init__(self, patch_func=None, **kwargs):
        super().__init__(**kwargs)
        self._patch_func = patch_func

    def _create_patch(self, legend, orig_handle, xdescent, ydescent,
                       width, height, fontsize):
        from matplotlib.patches import Rectangle
        if self._patch_func is not None:
            return self._patch_func(legend=legend, orig_handle=orig_handle,
                                     xdescent=xdescent, ydescent=ydescent,
                                     width=width, height=height,
                                     fontsize=fontsize)
        kwargs = {}
        for attr in ('facecolor', 'edgecolor', 'alpha', 'linewidth',
                      'linestyle', 'hatch'):
            getter = getattr(orig_handle, f'get_{attr}', None)
            if getter is not None:
                try: kwargs[attr] = getter()
                except Exception: pass
        return Rectangle((-xdescent, -ydescent), width, height, **kwargs)

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        return [self._create_patch(legend, orig_handle, xdescent, ydescent,
                                     width, height, fontsize)]


class HandlerLineCollection(HandlerBase):
    """Build a tiny Line2D from a :class:`LineCollection`'s segments."""

    def get_numpoints(self, legend):
        return getattr(legend, 'numpoints', None) or 1

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        xs = [-xdescent, width - xdescent]
        ys = [height / 2 - ydescent] * 2
        try:
            colors = orig_handle.get_color()
            c = colors[0] if hasattr(colors, '__len__') and len(colors) \
                and not isinstance(colors, str) else colors
        except Exception:
            c = None
        lw = None
        try:
            lws = orig_handle.get_linewidths()
            lw = lws[0] if hasattr(lws, '__len__') and len(lws) else lws
        except Exception:
            pass
        return [Line2D(xs, ys, color=c, linewidth=lw)]


class HandlerPathCollection(HandlerBase):
    """Draw a single scatter marker as the legend swatch."""

    def create_collection(self, orig_handle, sizes, offsets, transOffset):
        from matplotlib.collections import PathCollection
        return PathCollection(offsets=offsets, sizes=sizes)

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        try:
            face = orig_handle.get_facecolors()
            c = face[0] if hasattr(face, '__len__') and len(face) \
                and not isinstance(face, str) else face
        except Exception:
            c = None
        size = (height * 0.6)
        return [Line2D([width / 2 - xdescent], [height / 2 - ydescent],
                       marker='o', linestyle='None', markersize=size,
                       markerfacecolor=c, markeredgecolor=c)]


class HandlerRegularPolyCollection(HandlerBase):
    """Draw a regular polygon as the swatch."""

    def create_collection(self, orig_handle, sizes, offsets, transOffset):
        return None

    def get_numpoints(self, legend):
        return 1

    def get_sizes(self, legend, orig_handle, xdescent, ydescent, width,
                   height, fontsize):
        return [(height * 0.6) ** 2]

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        try:
            c = orig_handle.get_facecolors()
            if hasattr(c, '__len__') and len(c): c = c[0]
        except Exception:
            c = None
        n = getattr(orig_handle, 'numsides', 4)
        marker = {3: '^', 4: 's', 5: 'p', 6: 'h', 8: '8'}.get(int(n), 'o')
        return [Line2D([width / 2 - xdescent], [height / 2 - ydescent],
                       marker=marker, linestyle='None',
                       markersize=height * 0.6,
                       markerfacecolor=c, markeredgecolor=c)]


class HandlerCircleCollection(HandlerBase):
    """Draw a circle marker as the swatch."""

    def create_collection(self, orig_handle, sizes, offsets, transOffset):
        return None

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        try:
            c = orig_handle.get_facecolors()
            if hasattr(c, '__len__') and len(c): c = c[0]
        except Exception:
            c = None
        return [Line2D([width / 2 - xdescent], [height / 2 - ydescent],
                       marker='o', linestyle='None',
                       markersize=height * 0.6,
                       markerfacecolor=c, markeredgecolor=c)]


class HandlerErrorbar(HandlerBase):
    """Draw a vertical errorbar as the swatch."""

    def __init__(self, xerr_size=0.5, yerr_size=None, marker_pad=0.3,
                  numpoints=None, **kwargs):
        super().__init__(**kwargs)
        self._xerr_size = xerr_size
        self._yerr_size = yerr_size
        self._marker_pad = marker_pad
        self._numpoints = numpoints

    def get_err_size(self, legend, xdescent, ydescent, width, height, fontsize):
        return (self._xerr_size * fontsize,
                (self._yerr_size or self._xerr_size) * fontsize)

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        cx, cy = width / 2 - xdescent, height / 2 - ydescent
        xe, ye = self.get_err_size(legend, xdescent, ydescent, width, height, fontsize)
        line_h = Line2D([cx - xe, cx + xe], [cy, cy], color='C0')
        line_v = Line2D([cx, cx], [cy - ye, cy + ye], color='C0')
        return [line_h, line_v]


class HandlerStem(HandlerBase):
    """Draw a stem (vertical line + marker) as the swatch."""

    def get_ydata(self, legend, xdescent, ydescent, width, height, fontsize):
        return [0.0, height / 2 - ydescent]

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        from matplotlib.lines import Line2D
        cx = width / 2 - xdescent
        return [Line2D([cx, cx],
                       self.get_ydata(legend, xdescent, ydescent, width,
                                       height, fontsize),
                       linestyle='-'),
                Line2D([cx], [height / 2 - ydescent], marker='o',
                       linestyle='None')]


class HandlerTuple(HandlerBase):
    """Render multiple source handles side-by-side in a single swatch."""

    def __init__(self, ndivide=1, pad=None, **kwargs):
        super().__init__(**kwargs)
        self._ndivide = ndivide
        self._pad = pad

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                        width, height, fontsize, trans):
        if not orig_handle:
            return []
        # Divide the swatch width across the bundled handles.
        n = self._ndivide if self._ndivide and self._ndivide > 0 \
            else len(orig_handle)
        each_w = width / max(n, 1)
        artists = []
        for i, h in enumerate(orig_handle):
            handler = legend.get_legend_handler(
                legend.get_legend_handler_map(), h) if hasattr(legend, 'get_legend_handler') \
                else HandlerBase()
            if handler is None:
                continue
            try:
                sub = handler.create_artists(
                    legend, h,
                    xdescent - i * each_w, ydescent,
                    each_w, height, fontsize, trans)
                artists.extend(sub)
            except Exception:
                pass
        return artists


