class HandlerNpoints(HandlerBase):
    """Mixin-style base for handlers that draw a fixed number of points
    in the legend swatch (lines, errorbars, etc.). Stores ``numpoints``
    plus the marker padding so subclasses can lay out the swatch."""

    def __init__(self, marker_pad=0.3, numpoints=None, **kwargs):
        super().__init__(**kwargs)
        self._marker_pad = marker_pad
        self._numpoints = numpoints if numpoints is not None else 1

    def get_numpoints(self, legend):
        return self._numpoints


class HandlerNpointsYoffsets(HandlerNpoints):
    """:class:`HandlerNpoints` + a per-point vertical offset list. Used
    for errorbar handles where the cap markers sit above and below the
    central point."""

    def __init__(self, numpoints=None, yoffsets=None, **kwargs):
        super().__init__(numpoints=numpoints, **kwargs)
        self._yoffsets = yoffsets

    def get_ydata(self, legend, xdescent, ydescent, width, height, fontsize):
        n = self.get_numpoints(legend)
        if self._yoffsets is None:
            return [height / 2.0] * n
        # Match length, clipping or repeating the last value if needed.
        out = list(self._yoffsets)[:n]
        while len(out) < n:
            out.append(out[-1] if out else height / 2.0)
        return out


class HandlerPolyCollection(HandlerBase):
    """Handler for :class:`~matplotlib.collections.PolyCollection`. Plots
    a filled rectangle matching the collection's facecolor as its swatch.
    """

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                       width, height, fontsize, trans):
        from matplotlib.patches import Rectangle
        face = (orig_handle.get_facecolor()
                if hasattr(orig_handle, 'get_facecolor') else None)
        edge = (orig_handle.get_edgecolor()
                if hasattr(orig_handle, 'get_edgecolor') else None)
        # Most PolyCollection.get_*color returns a list; pick the first.
        if hasattr(face, '__len__') and len(face) and not isinstance(face, str):
            face = face[0]
        if hasattr(edge, '__len__') and len(edge) and not isinstance(edge, str):
            edge = edge[0]
        rect = Rectangle((-xdescent, -ydescent), width, height,
                         facecolor=face, edgecolor=edge)
        return [rect]


class HandlerStepPatch(HandlerPatch):
    """Handler for :class:`~matplotlib.patches.StepPatch`. The swatch is
    a step-shaped rectangle approximating the patch's profile."""

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                       width, height, fontsize, trans):
        from matplotlib.patches import Rectangle
        face = getattr(orig_handle, '_facecolor', None)
        rect = Rectangle((-xdescent, -ydescent), width, height,
                         facecolor=face)
        return [rect]


