class HandlerLine2DCompound(HandlerLine2D):
    """:class:`HandlerLine2D` variant that also draws the marker on top
    of the line in the legend swatch — mirrors how compound markers
    are rendered upstream."""

    def create_artists(self, legend, orig_handle, xdescent, ydescent,
                       width, height, fontsize, trans):
        # Tiny line + a single marker at its midpoint.
        from matplotlib.lines import Line2D
        xs = [-xdescent, width - xdescent]
        ys = [height / 2.0 - ydescent] * 2
        line = Line2D(xs, ys, linewidth=getattr(orig_handle, '_linewidth', 1.5),
                      color=getattr(orig_handle, '_color', None),
                      linestyle=getattr(orig_handle, '_linestyle', '-'))
        marker = Line2D([(xs[0] + xs[1]) / 2], [ys[0]],
                        marker=getattr(orig_handle, '_marker', None),
                        linestyle='None',
                        color=getattr(orig_handle, '_color', None))
        return [line, marker]


def update_from_first_child(tgt, src):
    """Copy visual properties (color, linewidth, linestyle, marker, alpha)
    from the first child of ``src`` onto ``tgt``. Used by the various
    handlers when they have to recolour generic placeholder artists to
    match the actual data."""
    children = []
    if hasattr(src, 'get_children'):
        children = list(src.get_children())
    elif isinstance(src, (list, tuple)):
        children = list(src)
    if not children:
        return
    first = children[0]
    for attr in ('color', 'linewidth', 'linestyle', 'marker', 'alpha',
                 'facecolor', 'edgecolor'):
        getter = getattr(first, f'get_{attr}', None)
        setter = getattr(tgt, f'set_{attr}', None)
        if getter and setter:
            try: setter(getter())
            except Exception: pass


# HandlerNpoints.get_xdata — uniformly spaced x-positions across the
# swatch (real handlers above already use this implicitly via xs=[0, w]).
def _hnp_get_xdata(self, legend, xdescent, ydescent, width, height, fontsize):
    """Return ``numpoints`` evenly-spaced x positions across the swatch."""
    import numpy as _np
    n = self.get_numpoints(legend)
    if n == 1:
        return _np.array([width / 2 - xdescent])
    return _np.linspace(-xdescent, width - xdescent, n)

HandlerNpoints.get_xdata = _hnp_get_xdata
